H.background();
const xLo = 0, xHi = 2 * Math.PI;
const v = H.plot2d({ xMin: xLo, xMax: xHi, yMin: -1.6, yMax: 1.6 });
v.grid(); v.axes();
const k = Math.max(-1, Math.min(1, P.k));    // target value
const hi = Math.max(0.2, Math.min(2 * Math.PI, P.hi));  // interval upper bound
// shade the allowed interval [0, hi] as a translucent band
v.rect(0, -1.6, hi, 3.2, { fill: "rgba(124,196,255,0.12)" });
v.fn(x => Math.cos(x), { color: H.colors.accent, width: 3 });
v.line(xLo, k, xHi, k, { color: H.colors.accent2, width: 2, dash: [6, 5] });
// cos(x) = k principal solutions on [0, 2π): a and 2π - a
const a = Math.acos(k);                       // [0, π]
const sols = [a, 2 * Math.PI - a];
for (let i = 0; i < sols.length; i++) {
  const xv = sols[i];
  const inside = xv >= 0 && xv <= hi;
  v.dot(xv, k, { r: 6, fill: inside ? H.colors.good : H.colors.sub });
}
const kept = sols.filter(x => x >= 0 && x <= hi);
// sweeping dot, but only travels across the allowed window so motion reads "restricted"
